// Khớp URL với mẫu thư mục: [id] một đoạn, [...slug] nhiều đoạn, [[...slug]] tuỳ chọn
function match(pattern, url) {
  const p = pattern.split("/").filter(Boolean), u = url.split("/").filter(Boolean);
  const params = {};
  for (let i = 0; i < p.length; i++) {
    const m = p[i].match(/^\[(\[)?\.\.\.(\w+)\]\]?$/);
    if (m) {                                   // catch-all
      const rest = u.slice(i);
      if (rest.length === 0 && !m[1]) return null;       // [...slug] bắt buộc >= 1 đoạn
      params[m[2]] = rest;
      return params;
    }
    const d = p[i].match(/^\[(\w+)\]$/);
    if (d) { if (!u[i]) return null; params[d[1]] = u[i]; }
    else if (p[i] !== u[i]) return null;
  }
  return p.length === u.length ? params : null;
}

console.log(JSON.stringify(match("/blog/[slug]", "/blog/hello")));
console.log(JSON.stringify(match("/docs/[...slug]", "/docs/a/b/c")));
console.log(JSON.stringify(match("/shop/[[...slug]]", "/shop")));

