function paramsOf(url) {
  const [a, slug, ...rest] = url.split("/").filter(Boolean);
  return a === "blog" && slug && rest.length === 0 ? { slug } : null;
}
console.log(JSON.stringify(paramsOf("/blog/hello-world")) + "|" + JSON.stringify(paramsOf("/about")));

